#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

int main(int argc, char *argv[])
{
    int i=0;
    char lever[1000000]= {0};
    int pivot=0,max=0;
    int64_t moment_l=0,moment_r=0;
    int has_newline = 0;

    if (fgets(lever, sizeof(lever), stdin) == NULL) return 0;
    size_t len = strlen(lever);
    if (len > 0 && lever[len-1] == '\n') {
        has_newline = 1;
    }
    max = (int)len;
    for (i=0; i<max; i++)
    {
        if (lever[i]=='^')
            pivot=i;
        else if (lever[i]=='=')
            lever[i]=0;
        else if (lever[i]=='\n')
            lever[i]=0;
        else
            lever[i]-='0';
    }
    for (i=0; i<pivot; i++)
    {
        moment_l+=lever[i]*(pivot-i);
    }
    for (i=pivot+1; i<max; i++)
    {
        moment_r+=lever[i]*(i-pivot);
    }
    if (moment_l>moment_r)
        printf("left");
    else if (moment_l<moment_r)
        printf("right");
    else
        printf("balance");
    if (has_newline)
        printf("\n");
    return 0;
}

